package main

import (
	"bytes"
	"sync"
)

var pool = sync.Pool{New: func() any { return new(bytes.Buffer) }}

func encode(s string) []byte {
	b := pool.Get().(*bytes.Buffer)
	b.Reset()
	defer pool.Put(b)
	b.WriteString(s)
	return append([]byte(nil), b.Bytes()...) // 返回前复制，避免共享 buffer
}
